const sc = document.querySelector('.notion-frame .notion-scroller');
window.__acc = window.__acc || new Map();
sc.scrollTop = 0; await new Promise(r=>setTimeout(r,800));
for (let i=0;i<120;i++){
  document.querySelectorAll('main [data-block-id]').forEach(el=>{ if(!el.querySelector('[data-block-id]')) window.__acc.set(el.dataset.blockId, [el.getBoundingClientRect().top + sc.scrollTop, el.innerText]); });
  sc.scrollTop += 400; await new Promise(r=>setTimeout(r,200));
}
[...window.__acc.values()].sort((a,b)=>a[0]-b[0]).map(x=>x[1]).join('\n').length

