* { box-sizing: border-box; }
body { margin: 0; font-family: system-ui, sans-serif; background: #f4f4f6; color: #1c1c1e; }
main { max-width: 760px; margin: 0 auto; height: 100vh; display: flex; flex-direction: column; padding: 16px; }
header { display: flex; align-items: baseline; justify-content: space-between; }
h1 { font-size: 1.3rem; margin: 0 0 12px; }
#status { font-size: 0.85rem; color: #666; }
#messages { flex: 1; overflow-y: auto; display: flex; flex-direction: column; gap: 8px; padding: 8px 0; }
.msg { padding: 10px 14px; border-radius: 12px; max-width: 85%; white-space: pre-wrap; line-height: 1.4; }
.msg.user { align-self: flex-end; background: #2f6fed; color: #fff; }
.msg.assistant { align-self: flex-start; background: #fff; border: 1px solid #ddd; }
.msg.error { align-self: flex-start; background: #fde8e8; color: #9b1c1c; border: 1px solid #f5b5b5; }
.meta { margin-top: 6px; font-size: 0.75rem; color: #888; }
form { display: flex; gap: 8px; padding-top: 8px; }
input { flex: 1; padding: 12px; border: 1px solid #ccc; border-radius: 10px; font-size: 1rem; }
button { padding: 12px 18px; border: 0; border-radius: 10px; background: #2f6fed; color: #fff; font-size: 1rem; cursor: pointer; }
button:disabled { opacity: 0.5; cursor: wait; }

